import{_ as e,o,c as s,a2 as r}from"./chunks/framework.G0y0PQA7.js";const a="/relio/shots/ko/start-welcome.png",i="/relio/shots/ko/start-update-ask.png",f=JSON.parse('{"title":"처음 시작하기","description":"","frontmatter":{},"headers":[],"relativePath":"quick/start.md","filePath":"quick/start.md"}'),l={name:"quick/start.md"};function n(p,t,c,g,u,d){return o(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="처음-시작하기" tabindex="-1">처음 시작하기 <a class="header-anchor" href="#처음-시작하기" aria-label="Permalink to &quot;처음 시작하기&quot;">​</a></h1><p>설치하고, 샘플로 둘러보고, 새 버전 알림을 켜는 데까지 5분이면 됩니다.</p><ol><li><p><strong>내려받기</strong> — <a href="https://github.com/relio-hq/relio/releases/latest" target="_blank" rel="noreferrer">Releases</a>에서 설치 파일 <code>Relio_&lt;버전&gt;_x64-setup.exe</code>를 받습니다. 설치 없이 쓰려면 <code>Relio_&lt;버전&gt;_x64_portable.zip</code>을 받아 압축을 풀고 <code>relio.exe</code>를 실행합니다.</p></li><li><p><strong>설치</strong> — 설치 파일을 실행합니다. 관리자 권한 없이 지금 사용자 계정에만 설치됩니다. &quot;Windows의 PC 보호&quot; 창이 뜨면 받은 곳이 맞는지 확인한 뒤 <strong>추가 정보 → 실행</strong>을 누릅니다(설치 파일에 아직 코드 서명이 없어서 나오는 경고입니다).</p></li><li><p><strong>첫 실행</strong> — 시작 화면에서 새 다이어그램, 파일 열기, 샘플 열기, 최근 파일을 고릅니다.</p><figure class="shot" data-scene="start-welcome"><img src="'+a+'" alt="시작 화면 — 새 다이어그램·파일 열기·샘플 열기·최근 파일" loading="lazy"><figcaption>시작 화면 — 새 다이어그램·파일 열기·샘플 열기·최근 파일</figcaption></figure></li><li><p><strong>샘플 열기</strong> — &quot;샘플 열기&quot;에서 PostgreSQL 샘플(온라인 서점)이나 MySQL 샘플(회원·권한 관리)을 고릅니다. 사본으로 열리므로 마음껏 고쳐 봐도 샘플은 그대로입니다.</p></li><li><p><strong>새 버전 알림 켜기</strong> — 처음 실행하면 창 아래에 &quot;새 버전이 나오면 알려 드릴까요?&quot; 띠가 뜹니다. <strong>알려 주세요</strong>를 누르면 Relio가 하루 한 번 공개 Releases에서 버전 정보만 받아 보고, 새 버전이 있으면 Relio 안에서 받아 설치합니다.</p><figure class="shot" data-scene="start-update-ask"><img src="'+i+'" alt="창 아래의 새 버전 알림 띠 — 알려 주세요 / 괜찮아요" loading="lazy"><figcaption>창 아래의 새 버전 알림 띠 — 알려 주세요 / 괜찮아요</figcaption></figure></li></ol><div class="tip custom-block"><p class="custom-block-title">팁</p><p>알림을 나중에 켜거나 끄려면 도구 › 환경 설정 › 일반의 &quot;새 버전 자동 확인 (하루 한 번)&quot;을 바꿉니다. 도움말 › 업데이트 확인…으로는 언제든 직접 확인할 수 있습니다.</p></div><p>지원: Windows 10·11(64비트). 새 버전 확인과 내려받기(켰을 때나 직접 확인할 때만) 말고는 모든 기능이 인터넷 없이 동작하고, 사용 기록이나 파일 내용을 밖으로 보내지 않습니다.</p><p><strong>자세히</strong> → <a href="/relio/features/file">파일</a> · <a href="/relio/features/update">업데이트</a> · <a href="/relio/features/preferences">환경 설정</a> · <a href="/relio/features/troubleshooting">도움말과 문제 해결</a></p>',6)])])}const h=e(l,[["render",n]]);export{f as __pageData,h as default};
